ALTER TABLE public.user_roles ADD COLUMN can_site_surveys boolean;
COMMENT ON COLUMN public.user_roles.can_site_surveys IS 'Per-member site survey capability. Null keeps role defaults (field staff on, office menu off).';
CREATE OR REPLACE FUNCTION public.member_survey_can() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.company_id=public.current_company_id() AND public.member_is_active(r.user_id) AND coalesce(r.can_site_surveys, r.role NOT IN ('superuser','admin'))) $$;
REVOKE ALL ON FUNCTION public.member_survey_can() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.member_survey_can() TO authenticated;
CREATE OR REPLACE FUNCTION public.my_member_capabilities() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('estimates',public.member_commercial_can('estimates'),'contracts',public.member_commercial_can('contracts'),'dispatch',public.member_dispatch_can(),'surveys',public.member_survey_can()) $$;
CREATE OR REPLACE FUNCTION public.set_member_surveys(_user uuid,_enabled boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.user_roles; BEGIN SELECT * INTO r FROM public.user_roles WHERE user_id=_user AND company_id=public.current_company_id() FOR UPDATE;
IF NOT FOUND OR auth.uid() IS NULL OR NOT public.member_is_active(auth.uid()) OR NOT(public.my_role()='superuser' OR (public.my_role()='admin' AND r.role<>'superuser')) THEN RAISE EXCEPTION 'Company office admin access required'; END IF;
UPDATE public.user_roles SET can_site_surveys=_enabled WHERE user_id=_user AND company_id=public.current_company_id(); END $$;
REVOKE ALL ON FUNCTION public.set_member_surveys(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.set_member_surveys(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_individual_survey_access() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF auth.uid() IS NOT NULL AND (TG_OP='INSERT' AND NEW.can_site_surveys IS NOT NULL OR TG_OP='UPDATE' AND NEW.can_site_surveys IS DISTINCT FROM OLD.can_site_surveys) AND NOT(NEW.company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND (public.my_role()='superuser' OR public.my_role()='admin' AND NEW.role<>'superuser')) THEN RAISE EXCEPTION 'Company office admin access required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER guard_individual_survey_access BEFORE INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.guard_individual_survey_access();
-- Members explicitly switched off cannot start new surveys; null keeps existing behaviour.
CREATE OR REPLACE FUNCTION public.member_survey_not_revoked() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=auth.uid() AND r.company_id=public.current_company_id() AND r.can_site_surveys IS FALSE) $$;
REVOKE ALL ON FUNCTION public.member_survey_not_revoked() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.member_survey_not_revoked() TO authenticated;
CREATE POLICY survey_capability_insert ON public.site_surveys AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (public.member_survey_not_revoked());